-- READ ONLY: aggregates only. Rows can contribute to more than one relation.
SELECT 'weeks.profile_id' AS relation, count(*) FILTER (WHERE c.user_id IS NOT NULL AND p.user_id IS NOT NULL AND c.user_id<>p.user_id) AS different_known_owners, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL) AS missing_owner, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL OR c.user_id<>p.user_id) AS invalid_total FROM public.weeks c JOIN public.profiles p ON p.id=c.profile_id
UNION ALL
SELECT 'weeks.generation_request_id' AS relation, count(*) FILTER (WHERE c.user_id IS NOT NULL AND p.user_id IS NOT NULL AND c.user_id<>p.user_id) AS different_known_owners, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL) AS missing_owner, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL OR c.user_id<>p.user_id) AS invalid_total FROM public.weeks c JOIN public.menu_generation_requests p ON p.id=c.generation_request_id
UNION ALL
SELECT 'pantry_items.profile_id' AS relation, count(*) FILTER (WHERE c.user_id IS NOT NULL AND p.user_id IS NOT NULL AND c.user_id<>p.user_id) AS different_known_owners, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL) AS missing_owner, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL OR c.user_id<>p.user_id) AS invalid_total FROM public.pantry_items c JOIN public.profiles p ON p.id=c.profile_id
UNION ALL
SELECT 'menu_generation_requests.profile_id' AS relation, count(*) FILTER (WHERE c.user_id IS NOT NULL AND p.user_id IS NOT NULL AND c.user_id<>p.user_id) AS different_known_owners, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL) AS missing_owner, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL OR c.user_id<>p.user_id) AS invalid_total FROM public.menu_generation_requests c JOIN public.profiles p ON p.id=c.profile_id
UNION ALL
SELECT 'menu_generation_requests.created_week_id' AS relation, count(*) FILTER (WHERE c.user_id IS NOT NULL AND p.user_id IS NOT NULL AND c.user_id<>p.user_id) AS different_known_owners, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL) AS missing_owner, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL OR c.user_id<>p.user_id) AS invalid_total FROM public.menu_generation_requests c JOIN public.weeks p ON p.id=c.created_week_id
UNION ALL
SELECT 'profiles.active_week_id' AS relation, count(*) FILTER (WHERE c.user_id IS NOT NULL AND p.user_id IS NOT NULL AND c.user_id<>p.user_id) AS different_known_owners, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL) AS missing_owner, count(*) FILTER (WHERE c.user_id IS NULL OR p.user_id IS NULL OR c.user_id<>p.user_id) AS invalid_total FROM public.profiles c JOIN public.weeks p ON p.id=c.active_week_id;
